    if line.strip():
        parts = line.split()
        if len(parts) >= 3 and parts[1] in ('T', 't'):
            try:
                addr = int(parts[0], 16)
                symbols.append((addr, ' '.join(parts[2:])))
            except:
                pass

symbols.sort()

# Find symbols for our addresses
targets = [0x2f4b20, 0x2f4c84]
for target in targets:
    best = None
    for addr, name in symbols:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        print(f'0x{target:x} -> {best[1]}+0x{target - best[0]:x} (base: 0x{best[0]:x})')
" 2>&1

